//! Transport abstraction: how opcode batches move from producer to consumer.
//!
//! The UI runtime produces renderer-neutral opcodes and knows nothing about the
//! transport. This module defines the boundary between:
//!
//! - the **producer** (opcode engine) that emits Frames, and
//! - the **consumer** (driver) that reads them.
//!
//! Local transports (shared-memory ring) may be zero-copy; remote transports
//! (WebSocket/IPC) copy and serialize. Both conform to the same traits.
//!
//! The two ends are deliberately separate traits because a transport is often
//! split across a process/IPC boundary: the producer and consumer may live on
//! different sides, with different backpressure and blocking semantics.

use pathland_opcode::Frame;

use crate::direction;

/// A batch of frames travelling through a transport.
///
/// This is the in-memory **transport unit**, distinct from a single `Frame`
/// (one emission). A transport may deliver one frame or coalesce several; it
/// may carry transport-level metadata. A zero-copy transport streams the frames
/// directly; a network transport serializes them.
#[derive(Debug, Clone, Copy)]
pub struct OpcodeBatch<'a> {
    frames: &'a [Frame<'a>],
    /// Transport direction (see [`crate::direction`]).
    direction: u16,
}

impl<'a> OpcodeBatch<'a> {
    /// Build a batch from a slice of frames.
    pub fn new(frames: &'a [Frame<'a>], direction: u16) -> Self {
        Self {
            frames,
            direction,
        }
    }

    /// The frames carried by this batch.
    pub fn frames(&self) -> &'a [Frame<'a>] {
        self.frames
    }

    /// Transport direction bitmask.
    pub fn direction(&self) -> u16 {
        self.direction
    }

    /// Whether this batch carries host → guest raw inputs.
    pub fn is_input(&self) -> bool {
        self.direction & direction::HOST_TO_GUEST != 0
    }
}

/// Errors produced by a transport.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProtocolError {
    /// The remote sent a version this side does not support.
    BadVersion,
    /// The payload is malformed (bad magic, truncated, bad length).
    Malformed,
    /// A raw input could not be interpreted.
    BadInput,
}

/// Errors produced by a transport while sending or receiving.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TransportError {
    /// The consumer has not drained; the producer should retain and retry.
    Backpressure,
    /// The transport is closed/terminated.
    Closed,
    /// Underlying IO failure.
    Io(u8),
    /// The peer violated the protocol.
    Protocol(ProtocolError),
}

/// Handles raw-input events arriving from the host (renderer → engine).
///
/// The driver resolves a raw input to a node id (via hit-testing) and dispatches
/// it here; the transport's guest side forwards it to the guest engine.
pub trait InputSink {
    /// Deliver a raw input (host → guest).
    fn dispatch(&mut self, event: &pathland_opcode::Event);
}

/// The producer side of a transport: the engine hands completed frames here.
pub trait FrameSink {
    /// Deliver a frame to the consumer. `flush` requests an immediate render.
    fn submit(&mut self, frame: &Frame<'_>, flush: bool) -> Result<(), TransportError>;
}

/// The consumer side of a transport: the driver reads frames here.
pub trait FrameSource {
    /// Non-blocking poll for the next batch of frames.
    ///
    /// Returns `None` when no frame is currently available.
    fn poll(&mut self) -> Result<Option<OpcodeBatch<'_>>, TransportError>;

    /// Blocking read of the next batch of frames.
    fn next(&mut self) -> Result<OpcodeBatch<'_>, TransportError>;
}

/// Combined producer-side transport bound by the engine.
pub trait DriverTransport: FrameSource {
    /// Send a raw input to the guest (host → guest over the same transport).
    fn send_input(&mut self, event: &pathland_opcode::Event) -> Result<(), TransportError>;
}

/// Combined consumer-side transport bound by the driver.
pub trait FrameSinkInput: FrameSink {
    /// Register the sink that receives host → guest inputs.
    fn set_input_sink(&mut self, sink: Box<dyn InputSink>);
}

//! Transport abstraction: how opcode batches move from producer to consumer.
//!
//! The UI runtime produces renderer-neutral opcodes and knows nothing about the
//! transport. This module defines the boundary between:
//!
//! - the **producer** (opcode engine) that emits opcodes, and
//! - the **consumer** (driver) that reads them.
//!
//! Local transports (shared-memory ring) may be zero-copy; remote transports
//! (WebSocket/IPC) copy and serialize. Both conform to the same traits.
//!
//! The two ends are deliberately separate because a transport is often split
//! across a process/IPC boundary, with different backpressure and blocking
//! semantics on each side.

use pathland_opcode::Frame;

/// A single in-memory transport unit: one frame of opcodes + arena plus
/// transport metadata. Distinct from the raw opcode stream and from the
/// wire-format batch.
#[derive(Debug, Clone, Copy)]
pub struct OpcodeBatch<'a> {
    frame: Frame<'a>,
    /// Transport direction bitmask (see [`crate::direction`]).
    direction: u16,
}

impl<'a> OpcodeBatch<'a> {
    /// Wrap a frame as a transport batch (guest → host by default).
    pub fn new(frame: Frame<'a>, direction: u16) -> Self {
        Self { frame, direction }
    }

    /// The frame carried by this batch.
    pub fn frame(&self) -> &Frame<'a> {
        &self.frame
    }

    /// Transport direction bitmask.
    pub fn direction(&self) -> u16 {
        self.direction
    }
}

/// Errors produced by a transport while sending or receiving.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TransportError {
    /// The consumer has not drained; the producer should retain and retry.
    Backpressure,
    /// The transport is closed/terminated.
    Closed,
    /// The peer violated the protocol.
    Protocol(ProtocolError),
}

/// Sub-errors for protocol violations.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProtocolError {
    /// The remote sent a version this side does not support.
    BadVersion,
    /// The payload is malformed (bad magic, truncated, bad length).
    Malformed,
    /// A raw input could not be interpreted.
    BadInput,
}

/// Handles raw-input events arriving from the host (renderer → engine).
///
/// The driver resolves a raw input to a node id (via hit-testing) and dispatches
/// it here; the transport's guest side forwards it to the guest engine.
pub trait InputSink {
    /// Deliver a raw input (host → guest).
    fn dispatch(&mut self, event: &pathland_opcode::Event);
}

/// The consumer side of a transport: the driver reads frames here.
///
/// A transport may be blocking or non-blocking; `next_frame` reflects that.
/// The returned `Frame` borrows the transport's backing memory (zero-copy when
/// possible); consume it before the next call.
pub trait FrameSource {
    /// Read the next available frame, or `None` if none is ready.
    ///
    /// Blocking vs non-blocking semantics are transport-specific (documented
    /// per implementation).
    fn next_frame(&mut self) -> Result<Option<OpcodeBatch<'_>>, TransportError>;
}

/// A consumer-side transport that can also send raw inputs back to the guest.
pub trait DriverTransport: FrameSource {
    /// Send a raw input from the host to the guest over this transport.
    fn send_input(&mut self, event: &pathland_opcode::Event) -> Result<(), TransportError>;
}

//! Shared-memory ring transport (zero-copy, SPSC).
//!
//! The producer (opcode engine) and consumer (native driver) share one linear
//! memory buffer containing the ring + arena. The producer writes 16-byte
//! opcodes via `pathland_opcode::Guest`; the consumer reads completed frames via
//! `pathland_opcode::Host`. No copying, no batching, no serialization — this is
//! the high-performance local path.

use pathland_opcode::{init_memory, Guest, Host, MemoryLayout};

use crate::traits::{DriverTransport, FrameSource, OpcodeBatch, TransportError};

/// A zero-copy SPSC shared-memory ring transport.
///
/// Owns the linear-memory buffer (header + ring + arena). Producers and
/// consumers are granted short-lived `Guest`/`Host` views over the same buffer
/// via the borrowed methods, so opcodes flow in place with no copies.
#[derive(Debug)]
pub struct RingTransport {
    /// Shared linear memory (header | ring | arena).
    mem: Vec<u8>,
    /// Ring/arena geometry.
    layout: MemoryLayout,
}

impl RingTransport {
    /// Create a ring transport with a default layout and a zeroed header.
    pub fn new() -> Self {
        let layout = MemoryLayout::default();
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);
        Self { mem, layout }
    }

    /// Create a ring transport over a caller-provided buffer/layout.
    pub fn with_buffer(mem: Vec<u8>, layout: MemoryLayout) -> Self {
        Self { mem, layout }
    }

    /// The memory layout (region geometry).
    pub fn layout(&self) -> &MemoryLayout {
        &self.layout
    }

    /// Create a producer view over the shared buffer (writes opcodes + arena).
    ///
    /// Drop the returned `Guest` before calling `next_frame`; producer and
    /// consumer must not overlap borrows.
    pub fn producer(&mut self) -> Guest<'_> {
        Guest::new(&mut self.mem, &self.layout)
    }

    /// Peak at the raw underlying buffer (for embedding/custom transports).
    pub fn buffer(&self) -> &[u8] {
        &self.mem
    }
}

impl Default for RingTransport {
    fn default() -> Self {
        Self::new()
    }
}

impl FrameSource for RingTransport {
    fn next_frame(&mut self) -> Result<Option<OpcodeBatch<'_>>, TransportError> {
        let mut host = Host::new(&mut self.mem, &self.layout);
        let mut frames = host.frames();
        match frames.pop() {
            Some(frame) => Ok(Some(OpcodeBatch::new(
                frame,
                crate::direction::GUEST_TO_HOST,
            ))),
            None => Ok(None),
        }
    }
}

impl DriverTransport for RingTransport {
    fn send_input(&mut self, event: &pathland_opcode::Event) -> Result<(), TransportError> {
        // Events cross the boundary as EVENT-category opcodes in the ring. The
        // host writes them at the producer side of the shared transport; a full
        // host → guest ring is reserved for a later phase. For now route through
        // the guest input path (in-process call).
        let _ = event;
        Err(TransportError::Protocol(
            crate::ProtocolError::BadInput,
        ))
    }
}

