//! Network batch transport (remote path).
//!
//! Producer side buffers Frames and serializes them (time/size policy) into
//! network batches; the consumer decodes batches back into `Frame` views. This
//! is the remote/SSR path where producer and consumer do **not** share memory.
//!
//! The wire format is unchanged from `crate::batch` (magic/version/flags/
//! frameCount/opcodeCount/opcodes/arenaDeltaLen/arena).

use alloc::vec::Vec;

use pathland_opcode::{Frame, Opcode};

use crate::batch::{decode_batch, encode_batch, BatchDecoder};
use crate::traits::{DriverTransport, FrameSource, OpcodeBatch, TransportError};
use crate::BATCH_VERSION;

/// Producer-side network batch encoder.
///
/// Buffers opcodes + arena deltas and serializes them into batches when
/// explicitly flushed (batching policy is applied by the caller, or use the
/// `Batcher` helper).
#[derive(Debug, Default)]
pub struct NetBatchEncoder {
    opcodes: Vec<Opcode>,
    arena_delta: Vec<u8>,
}

impl NetBatchEncoder {
    /// Append a frame's opcodes + arena delta to the pending batch.
    pub fn push_frame(&mut self, frame: &Frame<'_>) {
        let opcodes: Vec<Opcode> = frame.opcodes().collect();
        self.opcodes.extend(opcodes);
        // Arena delta: network transports mirror the arena; here the caller
        // supplies the used-arena slice when encoding. For the batch round trip
        // we serialize opcodes + an empty arena delta (strings travel once at
        // full-fidelity via `take_text`-style mechanisms or the arena in the
        // batch). See `encode_used_arena` for the full path.
        let _ = frame.arena();
    }

    /// Serialize the pending opcodes with a provided used-arena slice, clearing
    /// the buffer. `frame_count` is the covering frame counter.
    pub fn encode_with_arena(&mut self, frame_count: u32, arena_used: &[u8]) -> Vec<u8> {
        let bytes = encode_batch(frame_count, crate::direction::GUEST_TO_HOST, &self.opcodes, arena_used);
        self.opcodes.clear();
        self.arena_delta.clear();
        bytes
    }

    /// Whether any opcodes are buffered.
    pub fn is_empty(&self) -> bool {
        self.opcodes.is_empty()
    }
}

/// Consumer-side network transport: decodes batches into `Frame` views.
///
/// Owns a `BatchDecoder` (which mirrors the arena so absolute `arenaRef`
/// offsets stay valid). Bytes are fed in and the next decoded frame is yielded.
#[derive(Default)]
pub struct NetBatchConsumer {
    decoder: BatchDecoder,
}

impl NetBatchConsumer {
    /// Feed a raw batch (serialized via [`encode_batch`] / `NetBatchEncoder`).
    pub fn push_bytes(&mut self, bytes: &[u8]) -> Result<(), TransportError> {
        self.decoder.decode(bytes)?;
        Ok(())
    }

    /// The mirrored arena length (diagnostics).
    pub fn arena_len(&self) -> usize {
        self.decoder.arena_len()
    }
}

impl FrameSource for NetBatchConsumer {
    fn next_frame(&mut self) -> Result<Option<OpcodeBatch<'_>>, TransportError> {
        // The BatchDecoder holds the mirrored arena; the most recently decoded
        // batch's frame is re-exposed. For a streaming consumer the decoder is
        // keyed by the pending bytes; here we expose the last decoded frame.
        // A concrete socket transport would track pending frames explicitly.
        Err(TransportError::Protocol(
            crate::ProtocolError::Malformed,
        ))
    }
}

impl DriverTransport for NetBatchConsumer {
    fn send_input(&mut self, _event: &pathland_opcode::Event) -> Result<(), TransportError> {
        // Host → guest events over the network transport are reserved/planned.
        Err(TransportError::Protocol(
            crate::ProtocolError::BadInput,
        ))
    }
}

// Re-declare for documentation linkage.
#[allow(unused)]
fn _version() -> u16 {
    BATCH_VERSION
}

#[cfg(test)]
mod tests {
    use super::*;
    use pathland_opcode::{category, tree, Opcode};

    #[test]
    fn batch_encoder_decoder_round_trip_via_consumer() {
        // Encode a batch with opcodes + an arena delta.
        let frame_count = 3u32;
        let opcodes = [
            Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, 0x0002, 0),
            Opcode::new(category::STYLE, 0x01, 0, 1, 0x0001 | (0x04 << 16), 4.0f32.to_bits()),
        ];
        let arena = [1u8, 0, 0, 0, b'a'];
        let mut enc = NetBatchEncoder::default();
        // Feed opcodes via a synthetic frame is not trivial; directly push.
        enc.opcodes.extend_from_slice(&opcodes);
        enc.arena_delta.clear();
        let bytes = enc.encode_with_arena(frame_count, &arena);
        assert!(!bytes.is_empty());

        // Decode and validate.
        let mut consumer = NetBatchConsumer::default();
        consumer.push_bytes(&bytes).unwrap();
        assert_eq!(consumer.arena_len(), arena.len());
    }
}

//! Network batch transport (remote path).
//!
//! Producer side serializes Frames into network batches (opcodes + arena delta);
//! the consumer decodes them with `BatchDecoder` (see `crate::batch`) back into
//! `Frame` views consumed by `RenderTree::apply_frame`. This is the remote/SSR
//! path where producer and consumer do **not** share memory.
//!
//! The wire format is unchanged from `crate::batch` (magic/version/flags/
//! frameCount/opcodeCount/opcodes/arenaDeltaLen/arena).

use alloc::vec::Vec;

use pathland_opcode::{Frame, Opcode};

use crate::batch::encode_batch;

/// Producer-side network batch encoder.
///
/// Buffers opcodes (from Frames) and serializes them into a batch with the
/// arena's used-arena slice. Use the `Batcher` helper (`crate::batching`) for a
/// time/size flush policy; this type is the bare encoder for explicit flushes.
#[derive(Debug, Default)]
pub struct NetBatchEncoder {
    opcodes: Vec<Opcode>,
}

impl NetBatchEncoder {
    /// Append a frame's opcodes to the pending batch.
    pub fn push_frame(&mut self, frame: &Frame<'_>) {
        self.opcodes.extend(frame.opcodes());
    }

    /// Append raw opcodes to the pending batch.
    pub fn push_opcodes(&mut self, opcodes: &[Opcode]) {
        self.opcodes.extend_from_slice(opcodes);
    }

    /// Serialize the pending opcodes with a provided used-arena slice, clearing
    /// the buffer. `frame_count` is the covering frame counter.
    pub fn encode_with_arena(&mut self, frame_count: u32, arena_used: &[u8]) -> Vec<u8> {
        let bytes = encode_batch(
            frame_count,
            crate::direction::GUEST_TO_HOST,
            &self.opcodes,
            arena_used,
        );
        self.opcodes.clear();
        bytes
    }

    /// Whether any opcodes are buffered.
    pub fn is_empty(&self) -> bool {
        self.opcodes.is_empty()
    }

    /// Number of buffered opcodes.
    pub fn pending(&self) -> usize {
        self.opcodes.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use pathland_opcode::{category, tree, Opcode};

    #[test]
    fn encodes_and_clears() {
        let opcodes = [
            Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, 0x0002, 0),
            Opcode::new(
                category::STYLE,
                0x01,
                0,
                1,
                0x0001 | (0x04 << 16),
                4.0f32.to_bits(),
            ),
        ];
        let mut enc = NetBatchEncoder::default();
        enc.push_opcodes(&opcodes);
        assert_eq!(enc.pending(), 2);
        let arena = [1u8, 0, 0, 0, b'a'];
        let bytes = enc.encode_with_arena(3, &arena);
        assert_eq!(enc.pending(), 0);
        assert!(!bytes.is_empty());
    }
}

