// C ABI for the Pathland native host (cdylib `libpathland_native`).
// Documented in crates/pathland-native/src/capi.rs.

#ifndef PATHLAND_NATIVE_H
#define PATHLAND_NATIVE_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

// Opaque handle to a native host.
typedef void* pathland_native_host;

// Lifetime.
pathland_native_host pathland_native_create(void);
void pathland_native_destroy(pathland_native_host host);

// Flat builder (variants as raw u32: hstack=1, vstack=2, text=3, button=4, spacer=8).
uint8_t pathland_native_create_node(pathland_native_host host, uint32_t id, uint32_t component);
uint8_t pathland_native_insert_child(pathland_native_host host, uint32_t parent, uint32_t child, uint32_t index);
uint8_t pathland_native_remove_child(pathland_native_host host, uint32_t parent, uint32_t child);
uint8_t pathland_native_set_text(pathland_native_host host, uint32_t id, const char* text);
uint8_t pathland_native_set_property(pathland_native_host host, uint32_t id, uint32_t prop, uint32_t value);
uint8_t pathland_native_set_property_f32(pathland_native_host host, uint32_t id, uint32_t prop, float value);

// Engine.
uint8_t pathland_native_emit(pathland_native_host host);

// Zero-copy ring access (header at offset 0; see spec/OPCODE.md).
const uint8_t* pathland_native_ring_ptr(pathland_native_host host);
size_t pathland_native_ring_len(pathland_native_host host);
size_t pathland_native_layout_bytes(pathland_native_host host);
uint32_t pathland_native_root_id(pathland_native_host host);

#ifdef __cplusplus
}
#endif

#endif // PATHLAND_NATIVE_H

