public final class Dump {
    private Dump() {}

    static final int OFF_RING_OFFSET = 0x06;
    static final int OFF_SLOT_COUNT = 0x0E;
    static final int OFF_ARENA_OFFSET = 0x12;
    static final int OFF_ARENA_CURSOR = 0x18;
    static final int OFF_READ_CURSOR = 0x1C;
    static final int OFF_WRITE_CURSOR = 0x20;
    static final int OFF_FRAME_COUNT = 0x24;

    private static int u32(Pointer p, long off) { return p.getInt(off); }

    public static void main(String[] args) {
        Pointer host = PathlandNative.INSTANCE.pathland_native_create();
        Bridge bridge = new Bridge(host);

        View root = DSL.vstack(
                DSL.hstack(DSL.text("Count: 7"), DSL.button("Increment")).padding(16f),
                DSL.text("Pathland Java").color(0x888888)
        ).spacing(12f).padding(24f);

        Node tree = root.build();
        bridge.importTreeAndEmit(tree);

        Pointer mem = PathlandNative.INSTANCE.pathland_native_ring_ptr(host);
        long len = PathlandNative.INSTANCE.pathland_native_ring_len(host);

        System.out.println("ring_len=" + len);
        System.out.println("frameCount=" + u32(mem, OFF_FRAME_COUNT));
        System.out.println("ringOffset=" + u32(mem, OFF_RING_OFFSET));
        System.out.println("slotCount=" + u32(mem, OFF_SLOT_COUNT));
        System.out.println("arenaOffset=" + u32(mem, OFF_ARENA_OFFSET));
        System.out.println("arenaCursor=" + u32(mem, OFF_ARENA_CURSOR));
        System.out.println("readCursor=" + u32(mem, OFF_READ_CURSOR));
        System.out.println("writeCursor=" + u32(mem, OFF_WRITE_CURSOR));

        int ringOff = u32(mem, OFF_RING_OFFSET);
        int readCur = u32(mem, OFF_READ_CURSOR);
        int writeCur = u32(mem, OFF_WRITE_CURSOR);
        int n = writeCur - readCur;
        System.out.println("opcodes in frame: " + n);
        for (int i = 0; i < n && i < 20; i++) {
            long base = ringOff + (long) i * 16;
            int cat = mem.getByte(base) & 0xFF;
            int cmd = mem.getByte(base + 1) & 0xFF;
            int a = u32(mem, base + 4);
            int b = u32(mem, base + 8);
            int c = u32(mem, base + 12);
            System.out.printf("  [%d] cat=%02x cmd=%02x a=%d b=%d(0x%08x) c=%d%n",
                    i, cat, cmd, a, b, b, c);
        }

        PathlandNative.INSTANCE.pathland_native_destroy(host);
    }
}

